	/**
	 * Process the payment and return the result.
	 *
	 * @param  int $order_id
	 * @return array
	 */
	public function process_payment( $order_id ) {
		$order = wc_get_order( $order_id );

		// Validate USD currency requirement.
		if ( get_woocommerce_currency() !== 'USD' ) {
			wc_add_notice( __( 'Coinbase Business payments require USD store currency.', 'coinbase' ), 'error' );
			return array( 'result' => 'fail' );
		}

		// Create description for payment link based on order's products.
		try {
			$order_items = array_map( function( $item ) {
				return $item['quantity'] . ' x ' . $item['name'];
			}, $order->get_items() );

			$description = mb_substr( implode( ', ', $order_items ), 0, 500 );
		} catch ( Exception $e ) {
			$description = null;
		}

		$this->init_api();

		// Create a new payment link.
		$metadata = array(
			'order_id'  => strval( $order->get_id() ),
			'order_key' => $order->get_order_key(),
			'source'    => 'woocommerce',
		);

		$result = Coinbase_API_Handler::create_checkout(
			$order->get_total(),
			$metadata,
			$this->get_return_url( $order ),
			$this->get_cancel_url( $order ),
			$description
		);

		if ( ! $result[0] ) {
			self::log( 'create_checkout failed: ' . $result[1], 'error' );
			wc_add_notice( __( 'Unable to create checkout. Please try again or contact support.', 'coinbase' ), 'error' );
			return array( 'result' => 'fail' );
		}

		$checkout = $result[1];

		$order->update_meta_data( '_coinbase_checkout_id', $checkout['id'] );
		$order->update_meta_data( '_coinbase_checkout_url', $checkout['url'] );
		$order->save();

		return array(
			'result'   => 'success',
			'redirect' => $checkout['url'],
		);
	}

	/**
	 * Get the cancel url.
	 *
	 * @param WC_Order $order Order object.
	 * @return string
	 */
	public function get_cancel_url( $order ) {
		$return_url = $order->get_cancel_order_url();

		if ( is_ssl() || get_option( 'woocommerce_force_ssl_checkout' ) == 'yes' ) {
			$return_url = str_replace( 'http:', 'https:', $return_url );
		}

		/** DOCBLOCK - Makes linter happy.
		 *
		 * @since today
		*/
		return apply_filters( 'woocommerce_get_cancel_url', $return_url, $order );
	}

	/**
	 * Check payment statuses on orders and update order statuses.
	 */
	public function check_orders() {
		$this->init_api();

		// Check the status of non-archived Coinbase orders.
		$orders = wc_get_orders(
			array(
				'coinbase_archived' => false,
				'status' => array( 'wc-pending' ),
				'meta_query' => array(
					array(
						'key'     => '_coinbase_archived',
						'compare' => 'NOT EXISTS',
					),
					array(
						'relation' => 'OR',
						array(
							'key'     => '_coinbase_checkout_id',
							'compare' => 'EXISTS',
						),
						array(
							'key'     => '_coinbase_payment_link_id',
							'compare' => 'EXISTS',
						),
					),
				),
			)
		);

		foreach ( $orders as $order ) {
			$checkout_id = $order->get_meta( '_coinbase_checkout_id' );
			if ( empty( $checkout_id ) ) {
				$checkout_id = $order->get_meta( '_coinbase_payment_link_id' );
			}

			usleep( 300000 );  // Ensure we don't hit the rate limit.
			$result = Coinbase_API_Handler::get_checkout( $checkout_id );

			if ( ! $result[0] ) {
				self::log( 'Failed to fetch order updates for: ' . $order->get_id() );
				continue;
			}

			$data = $result[1];

			// Map checkout status to event type for _update_order_status().
			$event_type = isset( $data['status'] ) ? Coinbase_Constants::status_to_event_type( $data['status'] ) : null;
			if ( $event_type ) {
				$this->_update_order_status( $order, $event_type, $data );
			}
		}
	}

	/**
	 * Handle requests sent to webhook.
	 */
	public function handle_webhook() {
		include_once dirname( __FILE__ ) . '/includes/class-coinbase-constants.php';

		$payload = file_get_contents( 'php://input' );
		$this->process_webhook( $payload );

		status_header( 200 );
		exit;
	}

	/**
	 * Validate and process a Coinbase Business webhook payload.
	 *
	 * @param  string $payload Raw request body.
	 * @return bool Whether the webhook updated a matching Coinbase order.
	 */
	public function process_webhook( $payload ) {
		if ( empty( $payload ) || ! $this->validate_webhook( $payload ) ) {
			return false;
		}

		$data = json_decode( $payload, true );
		if ( ! is_array( $data ) ) {
			self::log( 'Ignoring webhook: invalid JSON payload.' );
			return false;
		}

		self::log( 'Webhook received event: ' . print_r( $data, true ) );

		$raw_event_type = isset( $data['eventType'] ) && is_string( $data['eventType'] ) ? $data['eventType'] : null;
		$event_type     = $raw_event_type ? Coinbase_Constants::normalize_event_type( $raw_event_type ) : null;
		$metadata       = isset( $data['metadata'] ) && is_array( $data['metadata'] ) ? $data['metadata'] : array();

		// Validate this is a WooCommerce payment.
		if ( ! isset( $metadata['source'] ) || 'woocommerce' !== $metadata['source'] ) {
			self::log( 'Ignoring webhook: not a WooCommerce payment.' );
			return false;
		}

		if ( ! isset( $metadata['order_id'] ) || ! is_scalar( $metadata['order_id'] ) ) {
			self::log( 'Ignoring webhook: no valid order_id in metadata.' );
			return false;
		}

		$order_id = absint( $metadata['order_id'] );
		$order    = $order_id ? wc_get_order( $order_id ) : false;

		if ( ! $order ) {
			self::log( 'Webhook error: order not found for ID ' . $order_id );
			return false;
		}

		if ( ! $this->validate_webhook_order( $order, $metadata, $data ) ) {
			return false;
		}

		$this->_update_order_status( $order, $event_type, $data );
		return true;
	}

	/**
	 * Ensure a webhook is bound to the Coinbase checkout that created an order.
	 *
	 * @param  WC_Order $order    WooCommerce order.
	 * @param  array    $metadata Webhook metadata.
	 * @param  array    $data     Full webhook payload.
	 * @return bool
	 */
	protected function validate_webhook_order( $order, $metadata, $data ) {
		$order_id = $order->get_id();

		if ( $this->id !== $order->get_payment_method() ) {
			self::log( 'Webhook error: order ' . $order_id . ' was not created with Coinbase.' );
			return false;
		}

		if ( ! isset( $metadata['order_key'] ) || ! is_scalar( $metadata['order_key'] ) ) {
			self::log( 'Webhook error: no order key for order ' . $order_id );
			return false;
		}

		$order_key = (string) $metadata['order_key'];
		if ( ! hash_equals( (string) $order->get_order_key(), $order_key ) ) {
			self::log( 'Webhook error: order key mismatch for order ' . $order_id );
			return false;
		}

		$checkout_id = $order->get_meta( '_coinbase_checkout_id' );
		if ( empty( $checkout_id ) ) {
			// Continue to support webhooks for orders made with the Payment Links API.
			$checkout_id = $order->get_meta( '_coinbase_payment_link_id' );
		}

		if ( empty( $checkout_id ) || ! isset( $data['id'] ) || ! is_scalar( $data['id'] ) ||
			! hash_equals( (string) $checkout_id, (string) $data['id'] ) ) {
			self::log( 'Webhook error: checkout identifier mismatch for order ' . $order_id );
			return false;
		}

		return true;
	}

	/**
	 * Validate Coinbase Business webhook signature.
	 *
	 * Verifies the x-hook0-signature header using HMAC-SHA256 with timestamp
	 * replay attack prevention.
	 *
	 * @param  string $payload Raw request body.
	 * @return bool
	 */
	public function validate_webhook( $payload ) {
		self::log( 'Checking Webhook response is valid' );

		$headers = array_change_key_case( getallheaders() );

		if ( ! isset( $headers[ Coinbase_Constants::SIGNATURE_HEADER ] ) ) {
			self::log( 'Missing signature header.' );
			return false;
		}

		$signature_header = $headers[ Coinbase_Constants::SIGNATURE_HEADER ];
		$secret           = 'yes' === $this->get_option( 'sandbox_mode' )
			? $this->get_option( 'sandbox_webhook_secret' )
			: $this->get_option( 'webhook_secret' );

		// Never authenticate a webhook with a publicly computable empty HMAC key.
		if ( empty( $secret ) ) {
			self::log( 'Webhook validation disabled: no webhook secret is configured.' );
			return false;
		}

		// Parse the signature header (format: t=timestamp,v0=sig,h=headers,v1=sig)
		$parts = array();
		foreach ( explode( ',', $signature_header ) as $part ) {
			$split = explode( '=', $part, 2 );
			if ( count( $split ) === 2 ) {
				$parts[ $split[0] ] = $split[1];
			}
		}

		$timestamp = isset( $parts['t'] ) ? $parts['t'] : null;
		$signature = isset( $parts['v0'] ) ? $parts['v0'] : null;

		if ( ! $timestamp || ! $signature ) {
			self::log( 'Invalid signature header format.' );
			return false;
		}

		// Replay attack prevention: reject if timestamp > 5 minutes old.
		if ( abs( time() - (int) $timestamp ) > 300 ) {
			self::log( 'Webhook signature timestamp too old.' );
			return false;
		}

		// Verify: hash_hmac('sha256', "$timestamp.$payload", $secret)
		$signed_payload     = $timestamp . '.' . $payload;
		$expected_signature = hash_hmac( 'sha256', $signed_payload, $secret );

		if ( hash_equals( $expected_signature, $signature ) ) {
			return true;
		}

		self::log( 'Webhook signature mismatch.' );
		return false;
	}

	/**
	 * Display admin notice when sandbox mode is active.
	 */
	public function sandbox_mode_notice() {
		if ( 'yes' !== $this->get_option( 'sandbox_mode' ) ) {
			return;
		}
		echo '<div class="notice notice-warning"><p>';
		printf(
			__( '<strong>Coinbase Business:</strong> Sandbox mode is active. No real funds will be transferred. <a href="%s">Disable sandbox mode</a> when ready to accept live payments.', 'coinbase' ),
			esc_url( admin_url( 'admin.php?page=wc-settings&tab=checkout&section=coinbase' ) )
		);
		echo '</p></div>';
	}

	/**
	 * Display an admin notice when webhook validation is not configured.
	 */
	public function webhook_secret_notice() {
		if ( 'yes' !== $this->get_option( 'enabled' ) || ! current_user_can( 'manage_woocommerce' ) ) {
			return;
		}

		$sandbox_mode = 'yes' === $this->get_option( 'sandbox_mode' );
		$secret       = $sandbox_mode
			? $this->get_option( 'sandbox_webhook_secret' )
			: $this->get_option( 'webhook_secret' );

		if ( ! empty( $secret ) ) {
			return;
		}

		$settings_url = admin_url( 'admin.php?page=wc-settings&tab=checkout&section=coinbase' );
		$secret_name  = $sandbox_mode ? __( 'sandbox webhook secret', 'coinbase' ) : __( 'webhook secret', 'coinbase' );

		echo '<div class="notice notice-error"><p>';
		printf(
			__( '<strong>Coinbase Business:</strong> Webhook processing is disabled because no %1$s is configured. <a href="%2$s">Configure the webhook secret</a> to receive payment updates securely.', 'coinbase' ),
			esc_html( $secret_name ),
			esc_url( $settings_url )
		);
		echo '</p></div>';
	}

	/**
	 * Init the API class and set credentials.
	 */
	protected function init_api() {
		include_once dirname( __FILE__ ) . '/includes/class-coinbase-constants.php';
		include_once dirname( __FILE__ ) . '/includes/class-coinbase-jwt-auth.php';
		include_once dirname( __FILE__ ) . '/includes/class-coinbase-api-handler.php';

		Coinbase_API_Handler::$log             = get_class( $this ) . '::log';
		Coinbase_API_Handler::$cdp_key_name    = $this->get_option( 'cdp_key_name' );
		Coinbase_API_Handler::$cdp_private_key = $this->get_option( 'cdp_private_key' );
		Coinbase_API_Handler::$sandbox_mode    = 'yes' === $this->get_option( 'sandbox_mode' );
	}

	/**
	 * Update the status of an order from a checkout event.
	 *
	 * @param  WC_Order $order      WooCommerce order.
	 * @param  string   $event_type Checkout event type.
	 * @param  array    $data       Full event data.
	 */
	public function _update_order_status( $order, $event_type, $data = array() ) {
		$prev_status = $order->get_meta( '_coinbase_status' );

		if ( $event_type === $prev_status ) {
			return;
		}

		$order->update_meta_data( '_coinbase_status', $event_type );

		if ( Coinbase_Constants::EVENT_PAYMENT_SUCCESS === $event_type ) {
			// Extract transaction ID from payment URL.
			$txn_id = ! empty( $data['url'] ) ? basename( $data['url'] ) : '';
			$order->payment_complete( $txn_id );
			$order->update_status( 'completed', __( 'Coinbase payment was successfully processed.', 'coinbase' ) );
		} elseif ( Coinbase_Constants::EVENT_PAYMENT_FAILED === $event_type ) {
			$order->update_status( 'failed', __( 'Coinbase payment failed.', 'coinbase' ) );
		} elseif ( Coinbase_Constants::EVENT_PAYMENT_EXPIRED === $event_type ) {
			if ( 'pending' === $order->get_status() ) {
				$order->update_status( 'cancelled', __( 'Coinbase payment expired.', 'coinbase' ) );
			}
		}

		// Archive if in a resolved state and idle more than timeout.
		if ( in_array( $event_type, array( Coinbase_Constants::EVENT_PAYMENT_EXPIRED, Coinbase_Constants::EVENT_PAYMENT_SUCCESS ), true ) &&
			$order->get_date_modified() < $this->timeout ) {
			self::log( 'Archiving order: ' . $order->get_order_number() );
			$order->update_meta_data( '_coinbase_archived', true );
		}

		$order->save();
	}

	/**
	 * Handle a custom 'coinbase_archived' query var to get orders
	 * paid through Coinbase with the '_coinbase_checkout_id' or
	 * '_coinbase_payment_link_id' meta.
	 *
	 * @param array $query - Args for WP_Query.
	 * @param array $query_vars - Query vars from WC_Order_Query.
	 * @return array modified $query
	 */
	public function _custom_query_var( $query, $query_vars ) {
		if ( array_key_exists( 'coinbase_archived', $query_vars ) ) {
			$query['meta_query'][] = array(
				'key'     => '_coinbase_archived',
				'compare' => $query_vars['coinbase_archived'] ? 'EXISTS' : 'NOT EXISTS',
			);
			$query['meta_query'][] = array(
				'relation' => 'OR',
				array(
					'key'     => '_coinbase_checkout_id',
					'compare' => 'EXISTS',
				),
				array(
					'key'     => '_coinbase_payment_link_id',
					'compare' => 'EXISTS',
				),
			);
		}

		return $query;
	}
}


